const body = $input.first().json.body;

if (!body || !body.text) {
  throw new Error('Missing required field: text');
}

let text = body.text;
const model = body.model || 'deepseek-r1:14b';

// Limit text to 6000 chars
if (text.length > 6000) {
  text = text.substring(0, 6000);
}

return [{
  json: {
    text: text,
    model: model
  }
}];

let response = $input.first().json.response;

if (!response) {
  throw new Error('No response from LLM');
}

// 1. Remove thinking tags (DeepSeek-R1 specific)
if (response.includes('<think>')) {
  const thinkEnd = response.lastIndexOf('</think>');
  if (thinkEnd !== -1) {
    response = response.substring(thinkEnd + 8).trim();
  }
}

// 2. Remove markdown code blocks
response = response.replace(/```json\s*/gi, '');
response = response.replace(/```\s*/gi, '');
response = response.trim();

// 3. Extract JSON
let jsonStr = response;
const firstBrace = response.indexOf('{');
const lastBrace = response.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace > firstBrace) {
  jsonStr = response.substring(firstBrace, lastBrace + 1);
}

// 4. Clean common JSON issues
jsonStr = jsonStr
  .replace(/,\s*}/g, '}')
  .replace(/,\s*]/g, ']')
  .replace(/\n/g, ' ');

// 5. Parse JSON
try {
  const parsed = JSON.parse(jsonStr);

  // Validate structure
  if (!parsed.vendor) parsed.vendor = {name: '', phone: '', address: '', contact: ''};
  if (!parsed.taxRate) parsed.taxRate = 0;
  if (!parsed.items) parsed.items = [];

  // Post-processing: Merge remark into description, then clear remark
  parsed.items = parsed.items.map(item => {
    if (item.remark && item.remark.trim()) {
      // Append remark content to description
      item.description = (item.description + '\n' + item.remark).trim();
    }
    // Always clear remark - all text should be in description
    item.remark = '';
    return item;
  });

  return [{ json: parsed }];
} catch (e) {
  throw new Error(`Failed to parse LLM response: ${e.message}`);
}
